import {frame,scale,axes,legend,esc} from '../shared.js';
import {seriesColors} from '../figure-themes.js';
export function render({data,params:p}){const keys=data.map(d=>JSON.stringify([d.category,d.group]));if(new Set(keys).size!==keys.length)throw Error('类别与分组组合重复，请先明确汇总方式');const f=frame(p),cats=[...new Set(data.map(d=>d.category))],groups=[...new Set(data.map(d=>d.group))],colors=seriesColors(p,[p.color,p.color2]),y=scale(data.flatMap(d=>[d.value-d.error,d.value+d.error]),f.bottom,f.top,p.yMin,p.yMax,true),slot=(f.right-f.left)/cats.length,bw=slot*.8/groups.length;let s=f.start+axes(f,null,y);data.forEach(d=>{const j=groups.indexOf(d.group),x=f.left+cats.indexOf(d.category)*slot+slot*.1+j*bw,b=y(Math.max(y.lo,Math.min(0,y.hi))),v=y(d.value),cx=x+bw*p.barWidth/2;s+=`<rect x="${x}" y="${Math.min(b,v)}" width="${bw*p.barWidth}" height="${Math.abs(b-v)}" fill="${esc(colors[j%colors.length])}"/><path d="M${cx},${y(d.value-d.error)}V${y(d.value+d.error)}M${cx-4},${y(d.value-d.error)}h8M${cx-4},${y(d.value+d.error)}h8" stroke="#29394d" fill="none"/>`;});cats.forEach((c,i)=>s+=`<text x="${f.left+(i+.5)*slot}" y="${f.bottom+25}" text-anchor="middle">${esc(c)}</text>`);return s+legend(f,p,groups,colors)+f.end;}
